/* لما الحقل يكون مكتوب فيه بيانات صحيحة ومطابقة للشروط */
input:valid {
  border-color: #10b981; /* أخضر */
}

/* ⚠️ انتبه: :invalid بيتطبق فوراً أول ما الصفحة تفتح لو الحقل required فاضي! */
/* الحل الحديث والأفضل: :user-invalid (بيتطبق بس بعد ما المستخدم يحاول يكتب ويغلط) */
input:user-invalid {
  border-color: #ef4444; /* أحمر */
  background-color: #fef2f2;
}

/* تنسيق الحقول الإلزامية */
input:required {
  border-right: 3px solid #3b82f6;
}

