const modal = document.querySelector('#profile-dialog');
const openBtn = document.querySelector('#open-modal-btn');
const cancelBtn = document.querySelector('#cancel-btn');

// فتح النافذة كـ Modal حقيقي (بيغمق الخلفية ويحبس التركيز)
openBtn.addEventListener('click', () => {
  modal.showModal(); // 💡 showModal() أفضل دايماً من show() العادية
});

