});

/* تلوين الخلفية المظلمة وراء الـ dialog بتأثير Blur جميل */
dialog::backdrop {
  background-color: rgba(0, 0, 0, 0.6);
  backdrop-filter: blur(4px);
}

// استنساخ القالب وتعبئته بالبيانات بالجافاسكربت
const template = document.querySelector('#product-card-template');
const container = document.querySelector('#products-list');

function renderProduct(product) {
  // عمل نسخة حقيقية من محتوى القالب
  const clone = template.content.cloneNode(true);

  clone.querySelector('.card-img').src = product.image;
  clone.querySelector('.card-img').alt = product.title;
  clone.querySelector('.card-title').textContent = product.title;
  clone.querySelector('.card-price').textContent = `$${product.price}`;

  container.appendChild(clone);
}

