// إنشاء مستند HTML مستقل برمجياً وتنزيله بضغطة زر
function downloadStandaloneReport(title, data) {
  const htmlContent = `
    <!DOCTYPE html>
    <html lang="ar" dir="rtl">
    <head><meta charset="UTF-8"><title>${title}</title></head>
    <body style="font-family: sans-serif; padding: 20px;">
      <h1>${title}</h1>
      <p>تاريخ الإنشاء: ${new Date().toLocaleString('ar-EG')}</p>
      <p>${data}</p>
    </body>
    </html>
  `;

  // تحويل النص لكائن ثنائي في الذاكرة
  const blob = new Blob([htmlContent], { type: 'text/html;charset=utf-8' });
  const blobUrl = URL.createObjectURL(blob);

  // إنشاء رابط تنزيل وهمي والضغط عليه تلقائياً
  const tempLink = document.createElement('a');
  tempLink.href = blobUrl;
  tempLink.download = 'offline-report.html';
  tempLink.click();

  // تنظيف الذاكرة بعد التنزيل
  URL.revokeObjectURL(blobUrl);
}

function ProfileCard({ userId, defaultName }) {
  // حالة المتغير في الذاكرة (React State)
  const [username, setUsername] = useState(defaultName);

  const handleSave = () => {
    console.log("تم حفظ الاسم:", username);
  };

  return (
    <section className="profile-card" id={`user-${userId}`}>
      <label htmlFor="username-input">اسم المستخدم:</label>
      <input 
        type="text" 
        id="username-input" 
        className="form-control" 
        style={{ borderColor: 'blue', padding: '8px' }}
        value={username}
        onChange={(e) => setUsername(e.target.value)}
      />
      <button type="button" onClick={handleSave}>
        حفظ التعديل
      </button>
    </section>
  );
}

// ❌ غلط: إضافة div ملوش لازمة هيبوظ الـ CSS Grid والـ Semantics
function NavLinks() {
